from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate a uniform separator row or column that splits equal-sized panels.
    split = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r * 2 + 1 == h:
            split = ('row', r)
            break
    if split is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c * 2 + 1 == w:
                split = ('col', c)
                break
    if split is None:
        raise ValueError('no centered uniform separator found')
    axis, k = split
    if axis == 'row':
        a, b = grid[:k], grid[k + 1:]
        if not a or len(a) != len(b):
            raise ValueError('panels must match')
        flat_a = [x for row in a for x in row]
        flat_b = [x for row in b for x in row]
        common = set(flat_a) & set(flat_b)
        if len(common) != 1:
            raise ValueError('expected one shared palette color')
        shared = next(iter(common))
        return [[3 if a[r][c] == b[r][c] else shared
                 for c in range(w)] for r in range(len(a))]
    a = [row[:k] for row in grid]
    b = [row[k + 1:] for row in grid]
